1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public abstract class OwnerMapper {
20	
21	    /**
22	     * The highest membership level derivable at creation. Level 4 is reserved for tenure and is never
23	     * produced here, so the computed level is capped at this value.
24	     */
25	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
26	
27	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
29	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.of(owner.getCity()))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    public abstract OwnerDto toOwnerDto(Owner owner);
35	
36	    public abstract Owner toOwner(OwnerDto ownerDto);
37	
38	    @Mapping(target = "id", ignore = true)
39	    @Mapping(target = "pets", ignore = true)
40	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
41	
42	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
43	
44	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
45	
46	    /**
47	     * Computes an owner's numeric membership level, assigned at creation. The level starts at 1, gains 1
48	     * when an email is present, gains a further 1 when {@code namesakeCount} is 0, and is capped at
49	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
50	     *
51	     * @param owner the owner whose level is being computed
52	     * @return the membership level (between 1 and {@value #MAX_MEMBERSHIP_LEVEL} inclusive)
53	     */
54	    protected Integer membershipLevel(Owner owner) {
55	        int level = 1;
56	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
57	            level++;
58	        }
59	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
60	            level++;
61	        }
62	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
63	    }
64	
65	    /**
66	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
67	     * present, otherwise {@code 'PHONE'}.
68	     *
69	     * @param owner the owner whose contact preference is being computed
70	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
71	     */
72	    protected String contactPreference(Owner owner) {
73	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
74	    }
75	
76	    /**
77	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
78	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
79	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'}). This is the single key used for duplicate detection,
80	     * so the value returned here matches the one the create endpoint compares.
81	     *
82	     * @param owner the owner whose identity key is being derived
83	     * @return the owner's identity key
84	     */
85	    protected String identityKey(Owner owner) {
86	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
87	        String email = owner.getEmail() == null ? "" : owner.getEmail();
88	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
89	        return telephone + "|" + email + "|" + householdId;
90	    }
91	
92	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
93	        OwnerPageDto ownerPageDto = new OwnerPageDto();
94	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
95	        ownerPageDto.setPage(ownerPage.getNumber());
96	        ownerPageDto.setSize(ownerPage.getSize());
97	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
98	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
99	        return ownerPageDto;
100	    }
101	}
102

